let s,loadStatus,saved,guide,vus,audioSet;{const l=loadSave((()=>{try{return localStorage}catch{return {getItem(){throw Error()}}}})(),Date.now());s=l.s;loadStatus=l.status;saved=l.fight||{};guide=l.guide||'todo';vus=l.vus||[];audioSet=normaliserReglages(l.audio)}
let paused=false,cool=saved.cool||0,f=restoreFight(s,saved),saveOk=true;
