function log(t){$('message').textContent=t}function setVit(t){$('vitdelta').textContent=t}const gain=n=>n>0?` · +${n} vitalité`:'';function save(){s.last=Date.now();let ok=false;try{ok=writeSave(localStorage,s,{hp:f.hp,boss:f.boss,enemyHP:f.enemyHP,cool},guide,vus,audioSet)}catch{}if(!ok){saveOk=false;$('saved').textContent='Sauvegarde indisponible'}else if(!saveOk){saveOk=true;$('saved').textContent='● Sauvegarde automatique'}}
