function annonce(m){const a=$('alert');a.textContent='';if(m)requestAnimationFrame(()=>{a.textContent=m})}
function apply(e){switch(e.type){
case'combat':emit('braise:combat',{damage:e.damage,strong:e.strong,defeated:e.defeated,boss:e.boss,health:e.health,taken:e.taken});if(e.taken>0)setVit(`−${e.taken} reçus`);$('float').textContent=`−${e.damage}`;$('float').classList.remove('hit');void $('float').offsetWidth;$('float').classList.add('hit');break;
case'spawn':emit('braise:spawn',{boss:e.boss});break;
case'levelup':log(`Niveau ${e.level} ! La braise grandit. Vitalité restaurée${e.healed>0?` (+${e.healed})`:''}.`);if(e.healed>0)setVit(`+${e.healed} soins`);break;
case'victory':log(`Ennemi vaincu · +${e.gold} or · +${e.xp} expérience${gain(e.healed)}`);if(e.healed>0)setVit(`+${e.healed} soins`);break;
case'bossVictory':log(`Gardien vaincu ! L’étage ${e.stage} s’ouvre. Vitalité restaurée${e.healed>0?` (+${e.healed})`:''}.`);if(e.healed>0)setVit(`+${e.healed} soins`);showBossPanel(e);break;
case'retreat':{const m=`Repli : ${e.boss?'le gardien':'l’ennemi'} frappait pour ${e.taken}, il lui restait ${Math.max(0,Math.ceil(e.enemyHP))} PV. Butin conservé.`;log(m);break}
case'bossStart':log('Le gardien approche. Fais parler la braise !');break;
case'upgrade':log(`${titles[e.kind]} : niveau ${e.level}${e.healed>0?` · +${e.healed} vitalité`:''}.`);if(e.healed>0)setVit(`+${e.healed} soins`);break}}
const BOSS_INTRO=`Le gardien est plus résistant (vie ×${BOSS_HP_MULT}) et frappe plus fort (riposte de base ${RETALIATION_BOSS_BASE} au lieu de ${RETALIATION_BASE}). Le vaincre ouvre l’étage suivant et rapporte ${BOSS_GOLD_MULT} fois l’or d’une victoire. Si tu perds, tu reviens au repli sans perdre ton butin.`;
const ABSENCE_INTRO=`Ton feu continue de brûler en ton absence : jusqu’à ${OFFLINE_CAP_SECONDS/3600} h de gains s’accumulent et tu les récupères à ton retour.`;
function showIntro(k,text){annonce(text);vus=[...vus,k];$(k==='gardien'?'bossintrotext':'absenceintrotext').textContent=text;$(k==='gardien'?'bossintro':'absenceintro').hidden=false;log(text)}
const PANNEAUX=['guidepanel','bossintro','absenceintro','bosspanel'];
function focusLogique(){for(const id of ['boss','power','pause']){const b=$(id);if(b&&!b.disabled&&b.offsetParent!==null){b.focus();return}}}
function fermer(id){const el=$(id);if(el.hidden)return;const dedans=el.contains(document.activeElement);el.hidden=true;if(dedans)focusLogique()}
function hideIntros(){fermer('bossintro');fermer('absenceintro')}
let guideAnnounced=false;const BOSS_PANEL_SECONDS=8;let bossPanelLeft=0;
function showBossPanel(e){$('bosspanel').hidden=false;$('bosstitle').textContent='Gardien vaincu';$('bossgold').textContent=`+${e.gold.toLocaleString('fr-FR')} or`;$('bossxp').textContent=`+${e.xp} expérience`;$('bossstage').textContent=`Étage ${e.stage} atteint`;bossPanelLeft=BOSS_PANEL_SECONDS}
function hideBossPanel(){bossPanelLeft=0;fermer('bosspanel');$('bosstitle').textContent=''}
function run(r){s=r.s;f=r.f;const m=annoncesPour(r.events);if(m)annonce(m);r.events.forEach(apply)}
const dangerText=a=>`${a.danger} · ${a.hitsToWin} coup${a.hitsToWin>1?'s':''} pour vaincre, ${a.hitsAbsorbed} encaissable${a.hitsAbsorbed>1?'s':''}`;
function render(){for(const [id,val] of Object.entries({gold:Math.floor(s.gold).toLocaleString('fr-FR'),stage:String(s.stage).padStart(2,'0'),floor:`Étage ${s.stage}${f.boss?' · Gardien':''}`,level:s.level,attack:attack(),health:`${Math.max(0,Math.ceil(f.hp))} / ${maxHP()}`,reward:reward(),xptext:`${s.xp} / ${xpNeeded(s)}`,progress:`${s.kills} / ${KILLS_PER_STAGE} ennemis vaincus`,enemy:f.boss?'Le Gardien de braise':names[(s.stage-1)%3],enemyhp:`${Math.max(0,Math.ceil(f.enemyHP))} / ${f.enemyMax}`}))$(id).textContent=val;{const a=assess(s,f);$('danger').textContent=`Puissance ${a.attack} par coup · ${dangerText(a)}`;$('danger').className='danger d-'+a.danger.toLowerCase().replace('û','u').replace('é','e')}$('xpbar').style.width=`${s.xp/xpNeeded(s)*100}%`;$('enemybar').style.width=`${f.enemyHP/f.enemyMax*100}%`;$('dots').innerHTML=Array.from({length:KILLS_PER_STAGE},(_,i)=>`<i class="${i<s.kills?'done':''}"></i>`).join('');$('boss').disabled=s.kills<KILLS_PER_STAGE||f.boss;$('boss').innerHTML=f.boss?'⚔ Gardien en cours…':`⚔ Affronter le gardien<small>${s.kills>=KILLS_PER_STAGE?'Prêt · ouvre le prochain étage':`${KILLS_PER_STAGE} victoires requises`}</small>${f.boss?'':`<small>Gardien : ${dangerText(assessGuardian(s))}</small>`}`;$('power').disabled=cool>0||paused;$('cooldown').textContent=cool>0?`Recharge · ${cool} s`:`Dégâts × ${SKILL_MULT} · prêt`;if(!vus.includes('gardien')&&(s.kills>=KILLS_PER_STAGE||f.boss)){showIntro('gardien',BOSS_INTRO);save()}const target=guide==='todo'&&s.gold>=cost(cheapestUpgrade(s))?cheapestUpgrade(s):null;$('guidehint').hidden=!target;if(target&&!guideAnnounced){guideAnnounced=true;log('Tu as assez d’or : achète ton premier objet !')}for(const k of ['weapon','armor','luck']){const b=$('buy-'+k);b.disabled=s.gold<cost(k);b.textContent=k===target?`◈ ${cost(k)} · À acheter`:`◈ ${cost(k)}`;if(k===target)b.classList.add('guided');else b.classList.remove('guided');$('desc-'+k).textContent=`Niv. ${s[k]} · ${k==='weapon'?`+${ATTACK_PER_WEAPON} attaque`:k==='armor'?`+${HEALTH_PER_ARMOR} vitalité`:`+${REWARD_PER_LUCK} or / victoire`}`}}
for(const [k,title,img] of [['weapon','Affûter la lame',104],['armor','Renforcer l’armure',100],['luck','Charme de fortune',110]]){const row=document.createElement('div');row.className='upgrade';row.innerHTML=`<img src="assets/Tiles/tile_${String(img).padStart(4,'0')}.png" alt=""><div><b>${title}</b><p id="desc-${k}"></p></div><button id="buy-${k}" aria-label="${title}"></button>`;$('upgrades').append(row);$('buy-'+k).onclick=()=>{if(s.gold<cost(k)){annonce(annoncePour({type:'achatImpossible'}));return}run(buyUpgrade(s,f,k));const first=guide==='todo';guide='done';if(first&&!vus.includes('absence'))showIntro('absence',ABSENCE_INTRO);save();render()}}
function strike(mult=1){if(paused)return;run(strikeOf(s,f,mult));render()}
$('boss').onclick=()=>{run(startBoss(s,f));render()};$('power').onclick=()=>{if(cool||paused)return;cool=SKILL_COOLDOWN_SECONDS;strike(SKILL_MULT)};$('pause').onclick=()=>{paused=!paused;emit('braise:pause',paused);$('pause').textContent=paused?'▶ Reprendre':'Ⅱ Pause';render()};$('reset').onclick=()=>{if(!confirm('Recommencer ? Toute la progression locale sera effacée.'))return;s=fresh();cool=0;guide='todo';vus=[];guideAnnounced=false;$('guidepanel').hidden=false;annonce($('guidepanel').firstElementChild.textContent);hideIntros();hideBossPanel();run(newFight(s));save();render();log('Une nouvelle braise s’éveille.')};$('export').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([serializeSave(s,{hp:f.hp,boss:f.boss,enemyHP:f.enemyHP,cool},guide,vus,audioSet)],{type:'application/json'}));a.download='braise-sauvegarde.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);log('Sauvegarde exportée.')};$('import').onclick=()=>$('importfile').click();$('importfile').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;let r={ok:false};try{r=importSave(await file.text(),Date.now())}catch{}if(!r.ok){log('Import refusé : fichier invalide, la partie en cours est inchangée.');return}if(!confirm('Importer cette sauvegarde ? La partie en cours sera remplacée.')){log('Import annulé.');return}s=r.s;guide=r.guide||'todo';vus=r.vus||[];audioSet=normaliserReglages(r.audio);renderAudio();fermer('guidepanel');hideIntros();cool=r.fight?.cool||0;hideBossPanel();f=restoreFight(s,r.fight);apply({type:'spawn',boss:f.boss});save();render();log('Sauvegarde importée.')};let avantBienvenue=null;$('claim').onclick=()=>$('welcome').close();$('welcome').addEventListener('close',()=>{const o=avantBienvenue;avantBienvenue=null;if(o&&o.isConnected&&o!==document.body&&!o.disabled)o.focus();else focusLogique()});$('bossclose').onclick=hideBossPanel;$('bossintroclose').onclick=()=>fermer('bossintro');$('absenceintroclose').onclick=()=>fermer('absenceintro');$('guideclose').onclick=()=>fermer('guidepanel');document.addEventListener('keydown',ev=>{if(ev.key!=='Escape'||$('welcome').open)return;const id=PANNEAUX.find(p=>$(p).contains(document.activeElement));if(id){id==='bosspanel'?hideBossPanel():fermer(id)}else if(!$('bosspanel').hidden)hideBossPanel()});
function collectAway(){const r=offlineGains(s,Date.now(),f,{paused});s=r.s;f=r.f;r.events.forEach(apply);if(r.show){$('offline').textContent=`Pendant ton absence : ${r.wins} ennemis vaincus et ${r.gold.toLocaleString('fr-FR')} pièces d’or récoltées (${OFFLINE_CAP_SECONDS/3600} h maximum). Les gains sont estimés et plafonnés à ${OFFLINE_CAP_SECONDS/3600} h d’absence.`;if(!$('welcome').open){avantBienvenue=document.activeElement;$('welcome').showModal();$('claim').focus()}}}
collectAway();
$('guidepanel').hidden=loadStatus!=='new';if(!$('guidepanel').hidden)annonce($('guidepanel').firstElementChild.textContent);hideIntros();
apply({type:'spawn',boss:f.boss});render();if(loadStatus==='reset'||loadStatus==='unavailable')log('Sauvegarde illisible ou indisponible : une nouvelle partie commence.');else if(loadStatus==='repaired')log('Sauvegarde endommagée : les valeurs invalides ont été remplacées.');if(loadStatus==='unavailable'){saveOk=false;$('saved').textContent='Sauvegarde indisponible'}setInterval(()=>{if(!document.hidden)strike()},ATTACK_INTERVAL_MS);setInterval(()=>{if(cool>0&&!paused)cool--;if(bossPanelLeft>0&&!paused&&!document.hidden&&--bossPanelLeft===0)hideBossPanel();render()},1000);setInterval(()=>{if(!document.hidden)save()},5000);document.addEventListener('visibilitychange',()=>{if(document.hidden)save();else{collectAway();render()}});window.addEventListener('pagehide',save);
// Audio : Web Audio natif, contexte créé ou repris seulement après une interaction. Les sons sont synthétisés (recettes dans engine/sons.js), déclenchés par la scène via `braise:son`.
let audioCtx=null,interacted=false;let bruitBuf=null;
function lireSon(r,gain){if(!audioCtx||audioCtx.state!=='running')return;try{const t0=audioCtx.currentTime,fin=t0+r.duree,g=audioCtx.createGain();g.gain.setValueAtTime(0.0001,t0);g.gain.linearRampToValueAtTime(Math.max(0.0001,r.pic*gain),t0+r.attaque);g.gain.exponentialRampToValueAtTime(0.0001,fin);let src;if(r.source==='bruit'){if(!bruitBuf){bruitBuf=audioCtx.createBuffer(1,Math.ceil(audioCtx.sampleRate*0.5),audioCtx.sampleRate);const d=bruitBuf.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1}src=audioCtx.createBufferSource();src.buffer=bruitBuf;const fl=audioCtx.createBiquadFilter();fl.type=r.filtre.type;fl.frequency.value=r.filtre.freq;fl.Q.value=r.filtre.q||1;src.connect(fl);fl.connect(g)}else{src=audioCtx.createOscillator();src.type=r.type;src.frequency.setValueAtTime(r.freq[0],t0);src.frequency.exponentialRampToValueAtTime(r.freq[1],fin);src.connect(g)}g.connect(audioCtx.destination);src.start(t0);src.stop(fin+0.02)}catch{}}
const audio=creerAudio({lire:lireSon});for(const [nom,r] of Object.entries(RECETTES))audio.enregistrer(nom,r);
window.addEventListener('braise:son',({detail})=>{jouer(detail.nom)});
function renderAudio(){const pct=Math.round(audioSet.volume*100);$('sound').setAttribute('aria-pressed',String(!audioSet.muet));$('sound').textContent=audioSet.muet?'♪ Son : coupé':'♪ Son : actif';$('volume').value=pct;$('volume').setAttribute('aria-valuetext',`${pct} %`);$('volumeout').textContent=`${pct} %`}
function syncAudio(){if(!interacted)return;const Ctx=window.AudioContext||window.webkitAudioContext;if(!audioCtx&&Ctx){try{audioCtx=new Ctx}catch{}}if(!audioCtx)return;if(peutJouer(audioSet,true,paused,document.hidden)){if(audioCtx.state==='suspended')audioCtx.resume().catch(()=>{})}else if(audioCtx.state==='running')audioCtx.suspend().catch(()=>{})}
function jouer(nom){return audio.jouer(nom,{reglages:audioSet,interactionFaite:interacted,pause:paused,masque:document.hidden})}
for(const ev of ['pointerdown','keydown','touchstart'])document.addEventListener(ev,()=>{if(interacted)return;interacted=true;syncAudio()},{capture:true,passive:true});
$('sound').onclick=()=>{audioSet={...audioSet,muet:!audioSet.muet};renderAudio();syncAudio();save()};
$('volume').oninput=e=>{audioSet={...audioSet,volume:Number(e.target.value)/100};renderAudio();syncAudio()};$('volume').onchange=save;
{const pauseClic=$('pause').onclick;$('pause').onclick=()=>{pauseClic();syncAudio()}}document.addEventListener('visibilitychange',syncAudio);
renderAudio();
